namespace HandyFix.Data.Seeding
{
    using System;
    using System.Collections.Generic;

    // The service pages' own blocks and questions, by the service's address, written with the
    // page text of the SEO plan's item 6 (PROJECT_STATE.md Section 3ep, then a section per batch
    // from 3eq). The seeder gives them to a new database; a database that already had the services
    // got the same text from the migration of its batch. A service not listed keeps its blocks empty.
    internal static class ServicePageTexts
    {
        public static readonly IReadOnlyDictionary<string, ServicePageText> BySlug = new Dictionary<string, ServicePageText>(StringComparer.Ordinal)
        {
            ["bath-shower-screen-fitting"] = new ServicePageText
            {
                Summary = "A glass bath or shower screen fixed through the tiles into the wall, hung upright, and sealed to its maker's instructions.",
                CommonFindings = "[water_drop] A screen sealed on the wrong side. Makers do not agree. Several UK makers say to seal the wall profile on the outside only, so water that gets behind it runs back into the bath; others ask for the inside, or both. We follow the screen's own instructions, since one maker warns that sealing against them ends the warranty.\n[construction] Tiles that crack when drilled. Glazed and porcelain tiles are drilled with a tile or diamond bit and the hammer action off, slowly, so the glaze does not chip round the hole.\n[search] A bath that is not level. Screen instructions ask for the bath to be level before the profile is sealed, or water collects at one end. We check it with a level first, and adjust a bath on feet.\n[warning] A chip on the edge of the glass. Toughened glass is strong across its face, but damage to an edge weakens the whole panel, so a chipped one is not fitted.",
                VisitSteps = "We take down the old screen, if there is one, and cut out its sealant.\nWe check the bath or tray is level, then hold the wall profile upright and mark its holes.\nWe drill the tiles, fix the profile, hang the glass and set it upright.\nWe seal the joints the instructions name and tell you how long to leave it before the bath or shower is used.",
                BeforeWeArrive = "[inventory_2] Unpack the screen when it arrives and check the glass edges and the parts against the list. Suppliers usually want damage reported before anything is fitted.\n[checklist] Say in your booking which screen it is, with the maker and the model, or add a photo of the box label.\n[home] Clear the bath or tray, its edge and the floor beside it.",
                Included = "Taking down an old screen and its sealant\nFixing the wall profile through the tiles\nHanging and setting fixed and hinged screens\nSealing to the screen's instructions",
                NotIncluded = "Retiling round the bath or shower: that is Wall & Floor Tiling\nSupplying the screen",
                Faqs = new[]
                {
                    ("Which side of a bath screen should be sealed?", "The side its maker's instructions say. Several UK makers say outside only, so water that gets behind the profile drains back into the bath, but others ask for the inside or both. Sealing against the instructions can void the screen's warranty."),
                    ("Will any screen fit my bath?", "No. A straight screen needs a straight bath edge. A shaped shower bath, wider at the shower end, takes the screen made for that bath and for its hand, left or right."),
                },
            },
            ["bathroom-plumbing"] = new ServicePageText
            {
                Summary = "A basin, bath, bidet or toilet swapped for a new one in the same place, its taps and waste connected and every joint tested dry.",
                CommonFindings = "[construction] A wall-hung basin on a stud wall. Plasterboard alone will not hold a basin and the weight of someone leaning on it, so it needs timber behind the board or a fixing frame.\n[build] Tap holes that do not match. A basin or bath with one tap hole takes a mixer, and one with two takes a pair of pillar taps, so the taps are chosen with the new piece.\n[plumbing] An outlet in a different place. A new toilet's outlet has to meet the old soil pipe, and a new basin's waste the old waste pipe, or the pipe behind is extended or moved.\n[info] A large bath. A bath that holds more than 230 litres, measured to the centre of its overflow, needs the water company's consent before it is fitted.",
                VisitSteps = "We turn off the water and isolate the supplies, and take the old piece out with its taps and waste.\nWe check the floor or wall where the new one goes, and fix its support, frame or legs.\nWe fit the new piece, its taps and its trap, with an isolating valve on each supply.\nWith the water back on, we fill and drain it, and check every joint until it stays dry.",
                BeforeWeArrive = "[checklist] Before you buy a new toilet, measure from the wall behind it to the middle of the old pan's outlet. The new one has to reach the same soil pipe.\n[inventory_2] Keep the new piece and its taps in their boxes, with the fitting instructions, so every part can be checked before the old one comes out.\n[home] Clear the bathroom floor and the shelves round the basin or bath.\n[add_a_photo] Add photos of the old piece and of the pipes under it to your booking.",
                Included = "Taking out the old basin, bath, bidet or toilet\nFitting the new one with its support, frame or legs\nConnecting the taps, waste and trap\nAn isolating valve on each supply\nTesting every joint dry with the water running",
                NotIncluded = "Moving a bath, basin or toilet to a new place, or retiling: that is Full Bathroom Refurbishment, priced after a survey",
                Faqs = new[]
                {
                    ("Do I need to tell the water company about a new bath?", "Only for a large one. The Water Fittings Regulations ask for notice and the water company's consent before fitting a bath that holds more than 230 litres, measured to the centre of the overflow. The capacity is in the bath's specification. If the company has not answered within ten working days, consent is taken as given."),
                    ("Can you fit a basin or toilet I have bought myself?", "Yes. Send us its name or a photo of the box when you book, so we can check its outlet and fixings suit the pipes and the wall it is going on."),
                },
            },
            ["blocked-drains"] = new ServicePageText
            {
                Summary = "Slow and blocked sinks, basins, baths, showers and toilets inside the house: the trap and waste pipe cleared and water run through. Outside drains are not included.",
                CommonFindings = "[water_drop] Fat in a kitchen waste. Cooking fat sets in the trap and the pipe behind it, and hot water does not shift it.\n[build] Hair and soap in a bath or shower trap. The water slows a little more each week until it stands in the tray.\n[warning] Wipes in a toilet. Thames Water's advice is that wet wipes block pipes, even the ones labelled flushable.\n[search] A waste pipe that runs too flat. Water sits in the pipe, and the same blockage comes back within weeks.\n[home] A blockage outside the house. When several fittings back up together, or water rises in a downstairs toilet as the bath empties, the blockage is usually in the drain outside.",
                VisitSteps = "We cover the floor and the cupboard, then take off the trap and clear it.\nWe clear the waste pipe beyond it with rods or a plunger, as the fitting needs.\nWe refit the trap, with new washers where the old ones are worn.\nWe run water through each fitting we cleared and check underneath for drips.",
                BeforeWeArrive = "[warning] Do not pour drain cleaner in before we come: it stays in the standing water and makes taking the trap off unsafe.\n[info] Check the other sinks, baths and toilets. If several are slow at once, tell us in your booking, as the cause may be outside.\n[inventory_2] Empty the cupboard under the sink and leave the bath panel clear.",
                Included = "Sinks, basins, baths, showers and toilets inside the house\nTraps and waste pipes, as far as where they leave the house\nNew trap washers where the old ones are worn",
                NotIncluded = "Outside drains, gullies and manholes\nShared drains and sewers, which the water company looks after",
                Faqs = new[]
                {
                    ("Who clears a blocked drain outside my house?", "It depends on the pipe. A drain that serves only your home, inside your boundary, is yours to have cleared. A pipe shared with neighbours, or past your boundary, has belonged to the sewerage company since 1 October 2011, and it clears those. Thames Water's website explains which pipes moved to it."),
                    ("Will hot water and washing-up liquid clear a greasy sink?", "No. Thames Water says hot water and soap do not dissolve fats and oils, and the soap can harden in the pipe. Let fat set in a jar or on foil and put it in the bin."),
                    ("What can go down a toilet?", "Pee, poo and toilet paper, and nothing else, as Thames Water puts it. Wipes, cotton wool, sanitary products, nappies, dental floss and hair all go in the bin."),
                },
            },
            ["boiler-installation-servicing"] = new ServicePageText
            {
                Summary = "New gas boilers fitted and existing ones serviced, all by our Gas Safe registered engineer, with a survey and a clear quote before any work starts.",
                CommonFindings = "[warning] Low pressure. Worcester Bosch puts the right reading at 1 to 1.5 bar with the system cold; below 1 bar a boiler may stop. Topping up more than once or twice a year points to a leak or a fault.\n[water_drop] A frozen condensate pipe. In a hard frost the plastic pipe that drains a condensing boiler outside can freeze. The boiler gurgles, stops and shows a fault code.\n[refresh] Sludge in the system. Radiators stay cold at the bottom and the boiler grows noisy. A new boiler goes in after the system is flushed, with a magnetic filter to catch what is left.",
                VisitSteps = "On installation day we turn off the water, drain the system and take out the old boiler, with any tanks or cylinders you no longer need.\nWe mount the new boiler level and secure, and fit and seal the flue through the wall.\nWe flush the system, fit a magnetic filter, and connect the flow, return, gas and condensate pipes.\nWe test everything, carry out the gas safety checks and set up your controls, smart thermostats included.\nWe hand over the compliance and warranty certificates, and notify the installation as Building Regulations require.",
                BeforeWeArrive = "[health_and_safety] If you smell gas, do not wait for a visit. Open doors and windows, turn the gas off at the meter, and call the National Gas Emergency number, 0800 111 999.\n[info] Have the boiler's make and model to hand, and any fault code it shows.\n[home] Clear the way to the boiler, the gas meter and the stop valve.",
                Included = "A survey and a clear quote before any work starts\nTaking out the old boiler, and any tanks or cylinders you no longer need\nFlushing the system and fitting a magnetic filter\nGas safety checks, your controls set up, and the compliance and warranty certificates\nA yearly service, with a written record of what was checked",
                NotIncluded = null,
                Faqs = new[]
                {
                    ("How often should a boiler be serviced?", "Once a year. Gas Safe Register advises a yearly service to keep gas appliances safe and working well, and most manufacturers need one to keep the warranty valid. We check that the boiler burns gas safely, test the flue and the pressure, clean the key parts and give you a record of the service."),
                    ("How do I check that an engineer is Gas Safe registered?", "Ask for the engineer's ID card and read both sides. The front has their photo and licence number; the back lists the work they are qualified for, which for a boiler should include gas boilers. The licence number can be checked on the Register's website."),
                    ("What paperwork comes with a new boiler?", "The warranty papers, and a Building Regulations Compliance Certificate. The installation has to be notified to the local authority within 30 days, which we do through Gas Safe Register. The Register then posts the certificate to you, and you can check online that it was done."),
                },
            },
            ["curtain-and-blind-fitting"] = new ServicePageText
            {
                Summary = "Curtain poles, tracks and blinds put up level, on fixings chosen for the wall above the window, with each cord or chain held out of a child's reach.",
                CommonFindings = "[warning] A steel lintel just above the window. A masonry bit will not drill it, so the brackets go into the brick above it, or the steel is drilled with a metal bit and the fixing chosen for steel.\n[build] A long pole that bows in the middle. Lined and interlined curtains are heavy, and a pole held only at its two ends sags between them, so a long pole gets a centre bracket as well.\n[home] A recess too shallow for the blind. A blind inside the recess needs room for its brackets and for the window handles to clear it. Where there is not enough, the blind goes on the wall above and overlaps the recess, which also keeps more light out.\n[health_and_safety] A cord or chain a child can reach. GOV.UK says the cleat that holds a blind's cord should be on a surface at least 1.5 metres from the floor, with the spare cord wound on in a figure of eight after each use.",
                VisitSteps = "We look at what is above and beside each window, and scan for cables and pipes before drilling.\nFor a blind in the recess, we check it against the recess at the top, the middle and the bottom.\nWe mark the brackets level, drill and fix them.\nWe hang the curtains or the blind and fit its cleat or chain tensioner.\nWe run each blind up and down and draw each curtain, to check it moves freely.",
                BeforeWeArrive = "[checklist] Say in your booking how many windows there are, and whether each has a pole, a track or a blind. Have them at home with all their brackets and screws.\n[home] Clear the window sills and move furniture away from the windows.\n[info] If an old pole or track is coming down, take the curtains off it if you can.",
                Included = "Curtain poles and tracks\nRoller, Roman, Venetian and vertical blinds\nCleats and chain tensioners fitted out of children's reach\nTaking down the old pole, track or blind",
                NotIncluded = "Electric blinds or tracks that have to be wired into the mains\nMaking or altering curtains and blinds",
                Faqs = new[]
                {
                    ("Does a blind with a cord need a safety device?", "Yes. GOV.UK says new blinds with looped cords must have child safety devices fitted when they are made, or sold with the blind, and the cleat goes at least 1.5 metres from the floor. An older blind without one can have a cleat or a chain tensioner added."),
                    ("Should a blind go inside the window recess or above it?", "Inside, if the recess is deep enough for the brackets and the window handles clear the blind: it looks neater and leaves the sill free. Above, overlapping the recess on each side, keeps out more light and suits a shallow recess."),
                },
            },
            ["custom-carpentry-boxing-in"] = new ServicePageText
            {
                Summary = "Alcove cupboards and shelving made to measure and built in place, and boxing for pipes with access at every valve, at a fixed price from a survey.",
                CommonFindings = "[build] Two alcoves that do not match. The alcoves either side of a chimney breast are seldom the same width, and their walls lean or bow, so each cupboard is built to its own alcove, with its sides shaped to the wall so that no gap shows.\n[plumbing] A soil pipe that is loud when the toilet flushes. Mineral wool packed round the pipe inside the boxing quietens it.\n[warning] A boiler flue where the boxing will go. HSE says a flue hidden in a void needs inspection hatches, and a gas engineer who finds one that cannot be inspected will advise that the boiler is \"at risk\" and, with the owner's permission, turn off its gas. Boxing round a flue is built with hatches.",
                VisitSteps = "At the survey we measure the alcoves or the pipe run, agree the design and the materials with you, and give you the fixed quote.\nWe build the frame in place, fixed to the wall and the floor.\nWe fit the doors, shelves and facings, and leave a panel that lifts out at every valve and joint in a boxing.\nWe fill the fixings and sand the joins, ready for paint.",
                BeforeWeArrive = "[checklist] Clear the alcoves, or the run of pipe to be boxed, and the floor in front of it.\n[plumbing] Show us at the survey where your stop valve and any other valves are, so the panels go in the right places.\n[water_drop] If boxing in a bathroom will be tiled, tell us at the survey. It is then built from moisture-resistant board, with the panel made to lift out with its tiles.",
                Included = "A survey and a fixed quote\nAlcove cupboards and shelving, made to measure and built in place\nBoxing for pipes along a wall, behind a toilet or in a corner\nAn access panel at every valve and joint behind boxing\nInspection hatches where boxing goes round a boiler flue\nFixings filled and joins sanded, ready for paint",
                NotIncluded = "Shelves on brackets and floating shelves: those are Shelf Installation, by the hour\nFlat-pack furniture: that is Furniture Assembly, by the hour",
                Faqs = new[]
                {
                    ("Can a stop valve be boxed in?", "Yes, if it can still be reached. Water Regs UK, in its guidance on the water fittings rules, says there must be access to the joints and fittings that need maintenance, such as the valves that control the flow. So the boxing is made with a panel there that you can take off."),
                    ("Can pipes be hidden inside the wall instead of boxed in?", "Only where nothing else will do. Water Regs UK's guidance says joints on concealed pipework are likely to lose their integrity over time, so concealing them should be considered only where it cannot be avoided. Boxing with a panel keeps them in reach."),
                },
            },
            ["door-repairs"] = new ServicePageText
            {
                Summary = "Sticking, dropped and rattling doors put right at the hinges, the latch or the edge, with draught strips and door closers fitted or adjusted.",
                CommonFindings = "[build] Loose hinge screws. The top hinge carries most of the door's weight, and when its screws work loose the door drops and rubs the frame at the top of the latch side.\n[lock] A latch that misses its keep. When the door has moved, the latch no longer meets the plate in the frame, so the door will not stay shut or it rattles. The keep is moved or adjusted to meet it.\n[water_drop] A door that sticks in damp weather. Bare or worn timber at the edges takes up moisture and swells. It is eased with a plane and the edge sealed again.\n[refresh] A closer that slams the door, or will not shut it. An overhead closer has valves that set how fast it swings and how hard it shuts.",
                VisitSteps = "We open and close the door, and look at where it rubs, how it hangs and how the latch meets the keep.\nWe tighten or refix the hinges first, since a door that has dropped needs no planing once they hold.\nWe plane an edge that still rubs, or move the keep, and seal any bare wood we have cut.\nWe check the door opens, closes and latches without force before we leave.",
                BeforeWeArrive = "[home] If it is your flat's front door, ask the building's managing agent first. In most blocks it is a fire door, and the government's guidance asks residents to report its faults and not to tamper with its closer.\n[add_a_photo] Add a photo of where the door rubs, or of the gap round it, to your booking.\n[inventory_2] If you have bought draught strips or a closer, keep them in their packets with the instructions.",
                Included = "Tightening, refixing or replacing hinges\nEasing a door that sticks, and sealing the planed edge\nMoving or adjusting the latch keep\nFitting draught strips and brush seals\nFitting or adjusting a door closer",
                NotIncluded = "Work on a fire door, including most flats' front doors: its seals, gaps and fittings are for a fire door specialist\nNew locks and handles: that is Lock & Handle Replacement",
                Faqs = new[]
                {
                    ("Why does my door stick only in winter?", "Because the timber takes up moisture in damp weather and swells, then shrinks back when it dries. Easing the edge and sealing it again keeps the damp out of the timber. We plane off only what it needs, or the door will have a gap in summer."),
                    ("How can I check that my flat's front door closes properly?", "The government's guidance gives a simple test: open the door fully and let it go, then open it to about 15 degrees and let it go. Both times it should close fully into the frame and latch without help."),
                },
            },
            ["door-trimming-shaving"] = new ServicePageText
            {
                Summary = "Doors that catch on new carpet, laminate or tiles taken off, trimmed to clear the floor, the cut edge sealed, and hung back.",
                CommonFindings = "[home] A door that drags across its whole width. The floor has risen under it, and the bottom edge needs trimming.\n[build] A door that catches at one corner only. It has usually dropped on a loose top hinge, and tightening the hinge cures it without a cut. That is a door repair.\n[warning] A hollow door. It has a solid timber frame round a hollow core, and its maker sets how much can come off. A cut past that opens the core.\n[info] A fire door. Fire doors are tested at their exact size, and the government's guidance asks a flat's front door to close by itself against any friction with the floor, so a new floor can stop one doing its job.",
                VisitSteps = "We measure from the floor with the door shut, and mark where the bottom edge has to come to.\nWe take the door off its hinges and cut the bottom edge against a straight guide, so the cut stays clean.\nWe seal the bare wood of the cut edge, so the door does not take up damp through it.\nWe hang the door back and check it swings over the new floor and closes on its latch.",
                BeforeWeArrive = "[timer] Wait until the new floor is down. A door trimmed for the underlay before the carpet goes on ends up being cut twice.\n[checklist] Count the doors that catch and put the number in your booking, so we can plan the time for all of them.\n[home] Clear the floor on both sides of each door.",
                Included = "Measuring each door from the finished floor\nTaking the door off and trimming the bottom edge\nSealing the cut edge\nHanging the door back and checking it closes",
                NotIncluded = "Trimming a fire door, including most flats' front doors: the gaps round it are set by its certificate\nTrimming a door by more than its maker allows: a door cut that far needs replacing",
                Faqs = new[]
                {
                    ("How much can you take off a door?", "As much as its maker allows, and that differs from door to door. A solid timber door can lose more than a hollow one, whose core opens once the cut goes past its frame. If the new floor needs more than the door can give, we tell you before we cut."),
                    ("Does a door need a gap underneath?", "Yes, so that air can move between rooms. Approved Document F, the government's ventilation guidance for new homes, gives 10mm above the floor finish for internal doors, or 20mm above the bare floor where the finish is still to go down."),
                },
            },
            ["emergency-plumbing"] = new ServicePageText
            {
                Summary = "Burst pipes, water through a ceiling and leaks that will not stop, taken by phone or WhatsApp at any hour. We aim to be with you within 60 to 90 minutes.",
                CommonFindings = "[warning] A pipe split by frost. Pipes freeze in a loft, a garage or an outside wall, and Thames Water warns that the leak often shows only when the weather turns milder and the ice thaws.\n[water_drop] A burst hose under a sink or behind a machine. A braided tap connector or a washing machine's fill hose gives way at full mains pressure, and the cupboard or the kitchen floor floods before anyone notices.\n[home] A tank or cistern that will not stop filling. The float valve in a loft tank or a toilet cistern sticks open, and what the overflow cannot carry away comes through the ceiling below.\n[plumbing] A stop valve that will not close. A stopcock left untouched for years can seize, or turn round and round without shutting anything off.",
                VisitSteps = "We make it safe first: the supply off at the stop valve, or at a valve nearer the leak so the rest of the house is not cut off.\nWhere water has reached a ceiling, a light or a socket, we check the electricity is off in that part of the house before we touch anything.\nWe find the burst or the failed fitting, opening boxing or lifting a floorboard where the pipe runs.\nWe cut out and replace the split length of pipe, remake the joint, or change the hose or valve that failed.\nWhen the full repair needs a part we do not carry, we cap or isolate that pipe so the supply can go back on to the rest of the house, and agree the part and its price with you.\nOnce the supply is back on, we check the repair at full pressure before we leave.",
                BeforeWeArrive = "[plumbing] Turn the water off at the inside stop valve. It is often under the kitchen sink, but WaterSafe notes it can be in a cupboard, a garage or a cellar. Turn it clockwise.\n[bolt] If water has reached the electrics, switch the electricity off at the mains, as Thames Water and WaterSafe both advise. Do not touch a switch, a socket or a fuse box that is wet.\n[timer] Turn the heating off, then open the hot and cold taps to drain what is left in the pipes.\n[inventory_2] Move what you can out of the way. Soak up the spill with towels, or catch the drips in a bucket.\n[emergency] If you smell gas, that is not a plumbing emergency. Call the National Gas Emergency Service on 0800 111 999, open the windows and doors, and do not touch any electrical switch.",
                Included = "Shutting off the supply and stopping the leak\nFinding the burst, opening boxing or lifting a floorboard where the pipe runs\nRepairing split pipes, failed joints, hoses and valves\nCapping or isolating a pipe until a part is fitted, so the rest of the house has water\nChecking the repair at full pressure",
                NotIncluded = "A leak in the road or the pavement: Thames Water's guidance is that the main and the pipe linking it to your supply pipe are the water company's, and it asks for leaks there to be reported to it\nA blocked or overflowing drain outside the house: we clear blockages indoors only\nA ceiling brought down by water: that is Plastering & Ceiling Repairs, priced after a survey",
                Faqs = new[]
                {
                    ("Who is responsible for a leak between the street and my house?", "You are, from the boundary of your property inwards. Thames Water's guidance is that the main and the communication pipe linking it to your supply pipe are the water company's, while the supply pipe under your garden or drive is the owner's, as is every pipe and fitting inside. If you rent, your landlord is responsible for fixing leaks."),
                    ("A pipe has frozen. What should I do?", "Turn the supply off at the stop valve and open the taps on that pipe, then thaw it slowly with a hot water bottle or warm towels wrapped round it, as Thames Water advises. Before turning the supply back on, run a dry cloth along the pipe: if it comes away wet, leave it off and call or WhatsApp us."),
                    ("Will my home insurance pay for the repair?", "That depends on your policy, so check it before anything else is spent, as Thames Water and WaterSafe both advise. Take photos of the damage, and keep the invoice we send for the repair."),
                },
            },
            ["external-brickwork-paving"] = new ServicePageText
            {
                Summary = "Repointing, garden wall repairs, patios relaid, outdoor steps rebuilt and shed bases laid, at a fixed price after a free survey.",
                CommonFindings = "[build] Mortar worn back from the face of the brick. Shallow new mortar on top of it does not last, so LABC's guidance is to rake the old joints out at least 12mm deep, and no more than 19mm, before repointing.\n[warning] Brick faces crumbling round hard pointing. A cement mortar that is stronger and less permeable than the brick sends the wet out through the bricks instead of the joints, and the bricks decay while the mortar stands proud. LABC says the mortar should be slightly weaker and more permeable than the brick, so the new mix is chosen to suit it.\n[water_drop] Slabs that rock or hold puddles. They are lifted, set on a new bed and laid to a fall so the rain runs off. Marshalls' guide asks for a fall of at least 1 in 80, and next to a house the fall runs away from it.\n[search] A garden wall that leans, or has cracked through the bricks. Repointing will not hold it, so the stretch that has moved is taken down and rebuilt.",
                VisitSteps = "At the survey we look at the wall, the joints or the paving, agree what is repaired and what is rebuilt, and give you the fixed quote.\nWe rake out the joints, take down the loose brickwork, or lift the slabs and clear the bed under them.\nWe repoint, rebuild or relay, with a mortar mixed to suit the brick.\nWe brush the new joints and clean the mortar off the faces of the bricks and slabs.\nWe cover fresh work when rain or frost is due.",
                BeforeWeArrive = "[directions_car] Tell us at the survey how we reach the back garden: by a side gate, or only through the house.\n[home] If the wall is on the boundary with a neighbour, talk to them before the work starts.\n[visibility] Note where water stands on the patio after rain, and which way it runs.",
                Included = "The survey at your home, with a fixed quote\nRaking out and repointing\nRebuilding a damaged stretch of garden wall\nLifting and relaying patio slabs on a new bed\nRebuilding outdoor steps\nConcrete bases for sheds",
                NotIncluded = "Driveways\nRetaining walls, the walls that hold back soil",
                Faqs = new[]
                {
                    ("Do I need planning permission to pave my front garden?", "Only for a hard surface that water cannot drain through, over more than five square metres, with no lawn or border for the rain to run to. Gravel and permeable block paving need no permission at any size. That is the Planning Portal's guidance for houses; flats and maisonettes have different rules."),
                    ("How high can a garden wall be without planning permission?", "One metre next to a road or its pavement, and two metres anywhere else, measured from the ground. That is the Planning Portal's guidance. A listed building, or a planning condition or council direction for the area, can take that right away."),
                    ("Can brickwork and paving be done in winter?", "On mild days. Marshalls' guide says paving is not laid when the temperature is below 5°C and falling, night-time included, and fresh mortar in brickwork needs the same care, so work in a cold spell waits for a milder day."),
                },
            },
            ["flooring-installation"] = new ServicePageText
            {
                Summary = "Laminate, LVT and engineered wood laid on a firm, level, dry base, with the right underlay, beading and door trims, at a fixed price from a survey.",
                CommonFindings = "[water_drop] A concrete floor that is still damp. New screed takes time to dry out, and an old slab may have no damp-proof membrane under it. Karndean's UK guide for its glue-down tiles asks for less than 75% relative humidity at the surface, so the concrete is tested first, and laminate goes down over a damp-proof membrane.\n[search] Boards that flex or dip. Old floorboards that move, or a floor that is out of level, show through a new floor as joints that click and open. Loose boards are screwed down and the low spots levelled before the underlay goes on.\n[home] A door that catches. The new boards and their underlay raise the floor, and a door that swung clear of the old carpet drags on them. We can trim it on the same visit.",
                VisitSteps = "At the survey we measure the rooms, look at the floor under the old covering, agree the flooring and where the joins and trims go, and give you the fixed quote.\nWe take up the old floor covering, with its underlay and any carpet gripper.\nWe make the base ready: loose boards screwed down, dips levelled, a damp-proof membrane over concrete.\nWe lay the underlay and the floor, keeping the gap at each wall that lets it move.\nWe fit the beading along the skirting and a trim at each doorway, then check that every door swings clear.",
                BeforeWeArrive = "[key] In a flat, read your lease before choosing a hard floor. Some leases ask for carpet, or for the landlord's consent and an acoustic underlay first.\n[add_a_photo] For the survey, have the name and maker of the flooring you like. The maker's instructions set the underlay and the gap at the walls.\n[home] The whole floor has to be clear on the day. Tell us at the survey about anything too heavy to move, such as a piano or a fitted wardrobe.",
                Included = "A survey of the rooms and a fixed quote\nTaking up the old floor covering\nScrewing down loose boards and levelling dips\nA damp-proof membrane over concrete\nUnderlay suited to the flooring\nBeading along the skirting and trims at the doorways",
                NotIncluded = "Carpet\nCeramic, porcelain and stone floors, which are Wall & Floor Tiling",
                Faqs = new[]
                {
                    ("How long does new flooring need to sit in the room before it is laid?", "At least 48 hours for laminate, in its unopened packs laid flat: that is Wickes's laminate guide. Karndean asks for its glue-down vinyl tiles to come out of their packs at least 24 hours before fitting, in the room they are for."),
                    ("Why does a laminate floor need a gap at the walls?", "Because laminate expands and contracts over time. Wickes's guide asks for a gap of 10 to 12mm all round the room, and warns that a floor laid without one can warp. The beading or the skirting covers it."),
                    ("Can I walk on a new vinyl floor straight away?", "Not on glue-down vinyl tiles. Karndean asks for them to be kept free of traffic for 24 hours after fitting, or covered with board or sheeting."),
                },
            },
            ["full-bathroom-refurbishment"] = new ServicePageText
            {
                Summary = "The old bathroom stripped out and a new one fitted: pipework, waterproofing, wall and floor tiles and sanitaryware, priced after a free survey at your home.",
                CommonFindings = "[water_drop] Soft floorboards under the old bath or toilet. Years of small leaks round a toilet or along the edge of a bath rot the boards, and they are replaced before anything new goes down.\n[warning] Plain plasterboard round the shower. The Tile Association's guide to BS 5385, the tiling standard, says plasterboard, moisture-resistant board included, is generally unsuitable for wet areas unless it is tanked. Walls like that are tanked or boarded again before tiling.\n[plumbing] No isolating valves. An older bathroom may have no valve on the pipes to the toilet and the taps, so we fit one to each, and a later repair needs no whole-house shut-off.\n[construction] Old tiles that bring the plaster with them. Tiles stuck on for decades can pull the plaster away as they come off, so the wall is boarded or plastered again before the new tiles go on.",
                VisitSteps = "We survey the room: we measure it, look at the pipes and the floor, agree the layout and the suite with you, and give you the fixed quote.\nWe take out the old suite and tiles and check the floor and walls underneath.\nWe run the new pipes and wastes, the registered electrician does the electrics, and we board and tank the walls that will get wet.\nWe tile the walls and the floor.\nWe fit and connect the new suite, seal it, and run every tap, the shower and the toilet to check for leaks.",
                BeforeWeArrive = "[add_a_photo] For the survey, have pictures of bathrooms you like, or the suite and tiles you have in mind.\n[key] If you live in a flat, read your lease or ask the managing agent whether the work needs the freeholder's consent, and when noisy work is allowed.\n[home] If this is your only bathroom, plan where you will wash while it is out of use, and tell us at the survey.",
                Included = "The survey at your home and a fixed quote\nTaking out the old suite and tiles\nNew pipework and wastes for the new layout\nBoarding and tanking the wet walls\nThe electrics round the bath or shower, by a registered electrician who certifies them\nWall and floor tiling\nFitting, connecting and sealing the new suite",
                NotIncluded = null,
                Faqs = new[]
                {
                    ("Does a bathroom refit need building regulations approval?", "Usually not. The Planning Portal says refitting a bathroom with new units and fittings does not generally need approval, but drainage or electrical work that is part of the refit may. In England, electrical work round a bath or shower is notifiable: an electrician registered with a competent person scheme certifies it, and you get a Building Regulations Compliance Certificate within 30 days."),
                    ("Do I have to fit an extractor fan?", "Not if the bathroom never had one. The Planning Portal says a refurbished bathroom must keep or replace any extract ventilation it already has, and one without it need not add it. A bathroom made in a room that was not one before does need extract ventilation."),
                },
            },
            ["furniture-assembly"] = new ServicePageText
            {
                Summary = "Flat-pack wardrobes, beds, desks and chests of drawers built in the room they belong in, and tall pieces fixed to the wall so they cannot tip.",
                CommonFindings = "[checklist] A part missing or damaged in the box. We check every part before we start, so you know at once and can ask the shop for it.\n[home] A wardrobe taller than the room allows. Built lying down, a tall wardrobe needs more than its own height to be stood up, so we check it against the ceiling before it is built.\n[warning] A thick carpet or an uneven floor. IKEA names both as causes of tipping. The unit is levelled where it stands, and still fixed to the wall.\n[refresh] Doors that do not line up. The hinges on flat-pack doors have adjusting screws, and they are set once the unit stands level in its place.",
                VisitSteps = "We unpack in the room where the furniture will stand and count the parts against the list.\nWe build it to the maker's instructions.\nWe stand it in its place, level it, and fix it to the wall where the maker supplies a fitting.\nWe set the doors and drawers so they close straight.",
                BeforeWeArrive = "[inventory_2] Have the boxes in the room where the furniture is going, with a clear patch of floor about the size of the unit lying down.\n[checklist] Say in your booking what you bought, with the maker and the model, or add a photo of the box label: the time a piece takes depends on it.\n[key] If you rent, check that you may drill the wall for the safety fitting.",
                Included = "Checking that every part is there\nBuilding it as the instructions show\nFixing tall pieces to the wall with the maker's fitting\nSetting the doors, hinges and drawers",
                NotIncluded = "Fitted furniture made to measure, such as an alcove cupboard: that is Custom Carpentry & Boxing-In, priced after a survey",
                Faqs = new[]
                {
                    ("What happens if a part is missing?", "We find out at the start, when we check the parts. If the piece cannot be finished without it, we stop there and you pay for the time used, with the one-hour minimum."),
                    ("Will fixing a chest of drawers to the wall leave marks?", "Two small screw holes behind it. IKEA's advice for when you move the furniture is simply to fill them."),
                },
            },
            ["general-handyman-call-out"] = new ServicePageText
            {
                Summary = "An hour of a handyman's time for a mix of small jobs, or one that is not on our list, with no call-out fee.",
                CommonFindings = "[inventory_2] A part we do not carry. A handle to match the others, a hinge of an old size or a length of trim is priced and agreed with you before it is bought.\n[construction] A job bigger than a visit. A new floor, a rebuilt wall or a refitted bathroom is not done by the hour: it is priced at a free survey, with a fixed quote.",
                VisitSteps = "We go through your list with you and agree the order, the job that matters most first.\nWe do the jobs one by one, and show you each one when it is done.\nWe tidy up, and tell you what, if anything, is left on the list.",
                BeforeWeArrive = "[checklist] Write the jobs down, in the order they matter to you.\n[add_a_photo] Add a photo of each job to your booking: a close-up, and one from a step back that shows the wall or the room.\n[home] Clear a space round each job, so the work can start straight away.",
                Included = "Several small jobs in the same booking\nJobs that are not on our list of services\nA price for any part needed, before it is bought",
                NotIncluded = "Plumbing, which is booked under Plumbing\nGas work, which is for our Gas Safe registered engineer\nNew circuits and other notifiable electrical work\nEmergencies, which are taken by phone or WhatsApp",
                Faqs = new[]
                {
                    ("Should I buy the materials before the visit?", "Yes, for anything you choose yourself: the shelf, the mirror, the handles, the curtain pole. Anything else the jobs need beyond what the technician carries is priced and agreed with you before it is bought."),
                    ("What if the list takes more than the hour?", "We start with the job that matters most to you, and say before the hour is up how much is left. You decide whether we carry on, or book the rest for another day."),
                },
            },
            ["general-plumbing-maintenance"] = new ServicePageText
            {
                Summary = "A visit to check the stop valve, the isolating valves, the loft tank and the pipes most likely to freeze, with small faults put right on the same visit.",
                CommonFindings = "[plumbing] A stop valve that will not turn, or will not shut. Left untouched for years it can seize, and the day it is needed is the day of a leak.\n[water_drop] A pipe dripping from the wall outside. It is a warning pipe from a toilet cistern or a loft tank, and it means the valve that fills it is not shutting off.\n[home] A loft tank without a proper lid. The Water Fittings Regulations ask for a storage tank to have a cover that keeps out light and insects, insulation against frost, and an overflow with a screen.\n[warning] Bare pipes in a cold place. Thames Water names pipes in unheated lofts, garages and utility rooms, along cold outside walls and to outside taps as the ones most likely to freeze.",
                VisitSteps = "We find the inside stop valve, turn it off and on again, and check the water stops.\nWe try each isolating valve under the sinks, toilets and appliances, and look at the joints and hoses round them.\nIn the loft, we look at the tank's lid, insulation and overflow, and the pipes up there.\nWe put right what can be done in the time booked, and tell you what is left and what it would cost.",
                BeforeWeArrive = "[key] Make sure we can get into the loft, the cupboard under the stairs and any utility room or garage with pipes in it.\n[search] If you do not know where your stop valve is, Thames Water says it is usually under the kitchen sink. We will find it if it is not.\n[checklist] Write down anything you have noticed: a tap that drips, a toilet that runs, a noise in the pipes, a damp patch.",
                Included = "Finding the inside stop valve and checking it shuts the water off\nTrying the isolating valves under sinks, toilets and appliances\nLooking at the hoses and joints round them\nChecking the loft tank's lid, insulation and overflow\nSmall fixes on the same visit, such as a washer or a valve\nA list of anything left, with what it would cost",
                NotIncluded = "A boiler service or any gas check: those are for our Gas Safe registered engineer, on the boiler page",
                Faqs = new[]
                {
                    ("What happens if the stop valve is seized?", "We do not force it, because a stop valve forced after years can start to leak at the spindle. We tell you, and a stop valve that does not shut is worth replacing: until it is, a burst cannot be stopped inside the house."),
                    ("What time of year suits a check?", "Before the first frost. Thames Water asks for bare pipes in lofts, garages and outside to be lagged before a cold spell, and the check shows which of yours need it."),
                },
            },
            ["gutter-clearing"] = new ServicePageText
            {
                Summary = "Gutters and downpipes cleared by hand and tested with water, with leaking joints and loose brackets found while we are up there.",
                CommonFindings = "[water_drop] An outlet blocked solid. Leaves and moss collect where the gutter drops into the downpipe, the water backs up behind them and spills over the front edge.\n[visibility] Stained brickwork under a joint. SPAB suggests looking at gutters and downpipes in heavy rain, when a leaking joint shows, or in dry weather for staining on the brick below it. A leaking joint gets a new seal or a new connector.\n[build] A gutter that falls the wrong way. SPAB's advice is to have gutters refixed if they slope the wrong way or pour water onto the wall. A loose or dropped bracket is reset so the gutter falls to its outlet.",
                VisitSteps = "We look at the gutters from the ground and agree with you where the ladder goes.\nWe scoop out the leaves, moss and silt by hand and bag them.\nWe clear each outlet and downpipe.\nWe run water along every length and watch where it goes.\nWe tell you about any joint, bracket or downpipe that needs more than a repair on the day.",
                BeforeWeArrive = "[directions_car] Move cars, bins and pots away from under the gutters, so the ladder can stand on firm ground.\n[info] Say in your booking how many storeys the house has, and whether a conservatory or an extension roof sits below any gutter.\n[visibility] If you have seen where water spills over in the rain, or birds going in and out under the roof, tell us.",
                Included = "Gutters at the front and the back\nOutlets and downpipes cleared\nA water test along every length\nResetting a loose bracket",
                NotIncluded = "Houses of more than two storeys\nDrains and gullies below the ground\nRoof repairs, such as slipped tiles or flashing",
                Faqs = new[]
                {
                    ("How often should gutters be cleared?", "Every autumn, once the leaves are down, and in spring as well: that is SPAB's advice. A house under trees may need it more often."),
                    ("Can you clear a gutter with birds nesting in it?", "Not the part with an active nest. The RSPB says an active nest must not be removed and the chicks must be allowed to leave first, so that stretch is cleared once the nest is empty. House sparrows and starlings are the birds it names as most likely to share a home."),
                },
            },
            ["kitchen-fitting-alterations"] = new ServicePageText
            {
                Summary = "A new kitchen fitted, or the one you have changed: units levelled and fixed, worktops cut and sealed, the sink and appliances connected, at a fixed price from a survey.",
                CommonFindings = "[water_drop] A wet or soft floor behind the old sink. A trap or a tap connector that dripped unseen for years shows when the old units come out. The leak is mended and the wet board cut out before a new unit goes over it.\n[build] A floor that falls and a wall that bows. The base units stand on legs set from the highest point of the floor, so the worktop runs level, and where the wall is not straight the back edge of the worktop is cut to follow it.\n[warning] A sink or hob drawn too close to the end of a worktop. Howdens' guide for its solid wood worktops says a cut-out should be at least 100mm from the end of the worktop and from the next cut-out, or the worktop is seriously weakened. We check the plan for it at the survey.",
                VisitSteps = "At the survey we measure the room, go through the kitchen plan with you, find where the water, the waste and the electrics run, and give you the fixed quote.\nWe turn off the supplies to the old kitchen, the gas by our Gas Safe registered engineer, and take it out.\nWe fit the base units level, then the wall units, checking the wall for cables and pipes before each fixing.\nWe cut and join the worktops, with the cut-outs for the sink and the hob, and seal every cut edge.\nWe fit the sink, the taps and the waste, connect the appliances, and fit the plinths, end panels and splashback.\nWe adjust the doors and drawers to line up, then run the water and check every joint under the sink before we leave.",
                BeforeWeArrive = "[checklist] Have the kitchen delivered before the first day, and open the boxes to check that every unit is there and undamaged. A missing unit stops the fitting at the point where it goes.\n[inventory_2] For the survey, have the supplier's plan and the model of each appliance. Each appliance's instructions set the space it needs and the supply it connects to.\n[home] Empty the cupboards, and plan where you will make a drink and wash up while the kitchen is out of use. We tell you at the survey how many days that will be.",
                Included = "A survey of the room and a fixed quote\nTaking out the old kitchen\nBase and wall units, levelled and fixed\nWorktops cut, joined and sealed, with the cut-outs for the sink and the hob\nThe sink, the taps and the waste connected\nAppliances fitted and connected\nPlinths, end panels, upstands and a splashback panel\nA new circuit, where an oven or a hob needs one, by a registered electrician we bring in\nA gas hob or cooker connected by our Gas Safe registered engineer",
                NotIncluded = "Taking out a wall that holds up a floor or the roof, which needs a structural engineer and a beam\nTiled splashbacks and tiled floors: those are Wall & Floor Tiling, priced after a survey",
                Faqs = new[]
                {
                    ("Can the sink move to another wall?", "Yes, if its waste pipe can reach the drain with a steady fall. Approved Document H, the government's guidance on drainage, gives the longest run and the slope a waste pipe can have without a vent of its own. Past them, it needs a vent or an air admittance valve, so the water seal in the trap is not pulled out. We look at the run at the survey."),
                    ("Why is there a gap between a wooden worktop and the wall?", "So the wood can move. Howdens' guide asks for 3 to 4mm at the back edge, because the worktop expands and contracts with the humidity of the kitchen, and at least 40mm beside a cooker that is always hot, such as an Aga or a Rayburn. An upstand, or the tiling and a silicone joint, covers the gap."),
                    ("Does a solid wood worktop need oiling before it is fitted?", "Yes, all over. Howdens' guide says both faces, any trimmed edges and the cut-outs must be oiled before installation, to cut the risk of the wood distorting, and every edge cut on site is oiled straight away."),
                },
            },
            ["kitchen-plumbing"] = new ServicePageText
            {
                Summary = "A kitchen sink fitted or replaced, with its waste, trap, tap feeds and isolating valves, and every joint under it checked dry with the taps running.",
                CommonFindings = "[build] A trap that drips. The nut on a plastic trap works loose, or its washer perishes, and a slow drip collects at the back of the cupboard.\n[warning] A swollen cupboard base. A slow leak goes unseen for months, until the chipboard base of the unit swells and comes apart.\n[water_drop] A failed seal between sink and worktop. Water from the draining board runs under the rim and into the cupboard, while every pipe is dry.\n[plumbing] A waste pipe with too little fall. When the pipe to the outside runs level, or rises anywhere along its length, water and scraps sit in it and the bowl drains slowly.",
                VisitSteps = "First the supply goes off, at the valves under the sink or at the stop valve where there are none.\nWe disconnect and take out the old sink or fittings, and look at the pipes and the cupboard behind them for signs of old leaks.\nWe fit the new sink, its waste and trap, and connect the tap feeds with an isolating valve on each.\nWe seal the rim to the worktop, turn the supply back on, fill and empty the bowl, and check every joint below it is dry.",
                BeforeWeArrive = "[inventory_2] Empty the cupboard under the sink.\n[add_a_photo] Photograph the pipes. Add the picture to your booking, with one of the new sink or tap if you have bought them.\n[search] If the new sink is a different size or shape, measure the old one and the new one, and say so in your booking.",
                Included = "Fitting a new or replacement kitchen sink, with its waste and trap\nConnecting the hot and cold feeds to the kitchen tap\nAn isolating valve on each feed\nSealing the sink to the worktop\nChecking every joint with the taps running",
                NotIncluded = "A blocked drain or gully outside the house: we clear blockages indoors only\nNew kitchen units or worktops: that is Kitchen Fitting & Alterations, priced after a survey",
                Faqs = new[]
                {
                    ("Does the kitchen cold tap have to come from the mains?", "In nearly every home, yes. The Water Fittings Regulations require at least one tap for drinking water, fed from the supply pipe or from a cistern that holds wholesome water, and the kitchen cold tap is the one used for it."),
                    ("Do I need valves under my kitchen sink?", "Yes, one on each tap feed. The Water Fittings Regulations ask for enough servicing valves to keep the water lost to a minimum when a fitting is repaired or replaced, and with them a tap can be changed while the rest of the house stays on."),
                },
            },
            ["leak-repairs"] = new ServicePageText
            {
                Summary = "Dripping joints, weeping valves and leaking pipes we can see or reach, under sinks, behind bath panels and at radiators, found, fixed and left dry under pressure.",
                CommonFindings = "[build] A loose or worn compression joint. A drop forms on the nut of a joint under a sink or at a valve, because the nut has worked loose or the brass ring inside has worn.\n[water_drop] A weeping valve. Isolating valves, radiator valves and stop valves leak round the spindle when they are turned after years untouched.\n[warning] A failed flexible hose. The braided hoses that feed many taps split, or rust at their ends.\n[home] A gap in the seal round a bath or shower. Water runs behind the bath and stains the ceiling below, while every pipe is dry.\n[search] A pinhole in old copper pipe. A fine jet or a steady drip from the middle of a pipe, with no joint near it.",
                VisitSteps = "We turn the water off at the nearest valve and dry everything, so a fresh drop shows where the leak starts.\nWe trace the water back to where it comes from, taking off a bath panel or kickboard where it leads.\nWe remake the joint, change the valve or hose, or cut out the bad length of pipe.\nWe turn the water back on, check the repair under pressure, and check it again before we leave.",
                BeforeWeArrive = "[plumbing] More than a drip? Turn the water off at the inside stop valve, which Thames Water says is usually under the kitchen sink and closes clockwise. Most homes also have valves that shut off one room.\n[emergency] Water coming through a ceiling, or near lights and sockets, cannot wait for a slot: keep away from wet electrics, and call or WhatsApp us.\n[add_a_photo] Add photos of the leak, and of any stain, to your booking.",
                Included = "Tracing a leak we can see or reach, opening a bath panel or kickboard where needed\nRemaking joints, and replacing valves, hoses and short lengths of pipe\nChecking the repair under full pressure",
                NotIncluded = "A leak hidden inside a wall or under a floor, that shows nowhere we can reach",
                Faqs = new[]
                {
                    ("How can I tell if there is a leak I cannot see?", "Thames Water lists the signs: less water from the cold kitchen tap than usual, damp patches in the garden in dry weather, pipes that are noisy when nothing is running, and a metered bill higher than it should be."),
                    ("Can you find a leak inside a wall or under a floor?", "Only when it shows itself where we can reach it: a joint behind a panel, or a damp patch we can follow back. We find leaks by eye and by testing, so one that cannot be traced that way needs a specialist to find it first."),
                },
            },
            ["lock-handle-replacement"] = new ServicePageText
            {
                Summary = "Euro cylinders, mortice locks, night latches and handles replaced, anti-snap cylinders and BS 3621 deadlocks included, so old keys no longer open the door.",
                CommonFindings = "[lock] A euro cylinder that can be snapped. An ordinary cylinder in a uPVC or composite door can be broken at its weak middle. Police guidance names a TS 007 3-star cylinder, or one approved to Sold Secure Diamond (SS312), both tested against snapping.\n[key] A timber door with only a night latch. For a solid timber door, police guidance asks for a five-lever mortice deadlock to BS 3621:2017. A night latch alone can be slipped or forced.\n[warning] A uPVC handle that is stiff to lift, or a key that will not turn. This is often the door that has dropped, so the locking points bind on their keeps. We check how the door sits before blaming the lock, since a new one would bind the same way.\n[refresh] A handle that droops. The spring inside the handle has worn, and the handle is replaced with one that matches the spindle and the screw holes already in the door.",
                VisitSteps = "We look at the door and the lock it has, and measure it: a euro cylinder from the fixing screw on the edge of the door to each end.\nWe check the door closes and the bolts meet their keeps without force.\nWe fit the new lock or handle, using the cut-outs already in the door where the new one matches them.\nWe test every key from both sides, with the door open and then closed.",
                BeforeWeArrive = "[info] Read what your home insurance policy says about locks. It may name the standard it needs.\n[add_a_photo] Add a photo of the lock and of the edge of the door to your booking. The plate on the edge often shows the maker and the standard.\n[key] Count the keys you have, and tell us if any are missing.",
                Included = "Euro cylinders in uPVC and composite doors, anti-snap ones included\nMortice locks and night latches in timber doors\nDoor handles and latches, inside and out\nA new set of keys with every new lock or cylinder",
                NotIncluded = "Getting in when you are locked out: that is for a locksmith\nLocks on a fire door, which in a block of flats includes the front door of each flat",
                Faqs = new[]
                {
                    ("What lock does my home insurance need?", "The one your policy names, so check its wording first. BS 3621 is the British Standard for a lock such as a mortice deadlock on a timber door, and police guidance asks for one to BS 3621:2017."),
                    ("How can I tell if my cylinder is anti-snap?", "Look at its face, beside the keyhole. A TS 007 cylinder carries the Kitemark and its stars. Three stars means the cylinder is rated on its own, without special handles. A Sold Secure Diamond one carries Sold Secure's mark. A cylinder with no mark at all is not one you can count on."),
                },
            },
            ["minor-electrical-tasks"] = new ServicePageText
            {
                Summary = "Switches, dimmers, sockets and light fittings replaced on your existing wiring, and smoke alarms fitted, with the circuit tested dead before work starts.",
                CommonFindings = "[bolt] A metal light fitting and no earth wire at the ceiling. Older lighting circuits often have no earth. A metal fitting needs one, unless it is double insulated: Class II, marked with a square inside a square. Where there is no earth, only a Class II fitting goes up.\n[info] LED bulbs that flicker on a dimmer. Many older dimmers were made for filament bulbs and have a minimum load the LEDs do not reach. A dimmer made for LEDs, with bulbs marked dimmable, stops it.\n[warning] A socket or switch with brown scorch marks, or one that crackles or smells hot. That is heat at the terminals. It is switched off and replaced, and if the cable behind it is damaged too, that is a job for an electrician.\n[timer] A smoke alarm past its date. Surrey Fire and Rescue Service says to replace a smoke alarm after 10 years, and to test it once a week. The date is usually on the back or the side.",
                VisitSteps = "We switch the circuit off at the consumer unit and test that it is dead before anything is touched.\nWe note how the old one is wired, then connect the new one to the same cables, with the earth where there is one.\nWe check every terminal is tight and the faceplate or fitting sits flat.\nWe switch back on and test it: the light, the socket with a socket tester, the alarm with its test button.",
                BeforeWeArrive = "[warning] If a socket or switch is hot, scorched or crackling, switch that circuit off at the consumer unit and do not use it until it is replaced.\n[home] Know where your consumer unit (fuse box) is, and keep the way to it clear.\n[inventory_2] If you have bought the new fitting, keep it in its box with its instructions, and say in your booking if it is heavy.",
                Included = "Replacing light switches and dimmer switches\nReplacing sockets, USB sockets included\nReplacing ceiling and wall light fittings\nFitting smoke alarms, and battery carbon monoxide alarms\nTesting each one after it is fitted",
                NotIncluded = "New circuits, a new consumer unit, and new wiring or additions in a bathroom: these are notified under Part P, and done by a registered electrician we bring in\nFinding a fault that keeps tripping a circuit\nA check of the whole installation (an Electrical Installation Condition Report)",
                Faqs = new[]
                {
                    ("Do I need an electrician to change a light fitting?", "Not by law in England, if the new fitting goes on the existing wiring. Part P does not ask for that to be notified. It still has to be done safely, which is why the circuit is tested dead before it is touched, and tested again when it is back on."),
                    ("What alarms does a landlord have to fit?", "In England, a smoke alarm on every storey with a room lived in, and a carbon monoxide alarm in any room with a fixed appliance that burns fuel, such as a boiler or a wood burner, but not a gas cooker. The rules have applied since 1 October 2022, and a faulty alarm has to be repaired or replaced once the tenant reports it."),
                },
            },
            ["minor-home-repairs"] = new ServicePageText
            {
                Summary = "Plaster cracks filled, creaking floorboards screwed down, and loose handles, hinges, rails and skirting fixed firm, by the hour.",
                CommonFindings = "[refresh] A crack that opens and closes with the seasons. NHBC, the new-home warranty body, says the materials of a house expand and shrink as the temperature and humidity change through the year, which leaves fine cracks where an outside wall meets a plasterboard one, along the joins of a plasterboard ceiling, and at the corners of skirting boards and architraves. A flexible filler suits these better than a hard one.\n[build] A floorboard that creaks. The board is moving against its nails or the board beside it. A screw down into the joist holds it still, once we have checked for pipes and cables under it.\n[handyman] A handle or a towel rail that keeps working loose. Its screws have worn their holes too big to grip, so the holes are plugged and drilled again, or the fixing is changed for one that suits the wall.\n[home] A cupboard door that hangs crooked or will not close. Most kitchen hinges have screws that adjust the door's height, depth and sideways position, and a few turns bring it square.",
                VisitSteps = "We go round the repairs on your list with you, and look at each crack before it is filled.\nWe rake out each crack, fill it, and sand it flush once the filler has set.\nWe screw down creaking boards and fix back whatever is loose.\nWe tell you about anything that needs more than a repair, such as a crack to show a surveyor.",
                BeforeWeArrive = "[checklist] List the repairs in your booking, with a photo of each.\n[visibility] Tell us how long each crack has been there, and whether it has grown.\n[home] Clear the floor over a creaking board: rugs and furniture off it.",
                Included = "Filling cracks in plaster, ready for paint\nScrewing down creaking floorboards\nFixing back loose handles, hinges, towel rails and skirting\nAdjusting kitchen cupboard doors on their hinges",
                NotIncluded = "Cracks wider than 5mm, or still growing, until a surveyor has seen them\nPainting over the repair, which is Painting Touch-Ups\nReplastering a wall or a ceiling, which is Plastering & Ceiling Repairs\nDripping taps and other plumbing, which are booked under Plumbing",
                Faqs = new[]
                {
                    ("Are cracks in a new house normal?", "Fine ones, usually. NHBC says the plaster, mortar and concrete of a new home hold a lot of water and shrink as they dry out, which can leave minor cracks in walls and floors, often along a wall near the ceiling or the floor. Those cracks normally stay the same width and are less than 2mm wide."),
                    ("When is a crack more than a repair?", "When it is wider than about 5mm, or getting wider. BRE, the Building Research Establishment, treats cracks up to 5mm wide, in general, as a matter of redecoration. It says whether a crack is getting wider can change that, and that a building professional should be consulted where the damage is significant."),
                },
            },
            ["outside-garden-tap-installation"] = new ServicePageText
            {
                Summary = "A new tap on the outside wall, fed from the cold supply, with its backflow protection and a shut-off valve fitted indoors, out of the frost.",
                CommonFindings = "[warning] An old tap with no backflow protection. Water Regs UK lists the ways to add it: a double check valve indoors on the tap's feed, a tap with one built in, or a device screwed onto the outlet.\n[water_drop] A tap or pipe split by frost. Water left standing in the tap and in the pipe through the wall freezes and expands, and WaterSafe warns that this can crack and burst them.\n[search] A cracked valve inside the tap. Some garden taps carry their check valve in the tap body, where Water Regs UK notes it is prone to freezing and failing.\n[plumbing] No way to shut the tap off on its own. Without a valve indoors, draining it for winter means turning off the water to the whole house.",
                VisitSteps = "We find the nearest cold pipe to where the tap will go, and check the wall for cables and pipes before drilling.\nWe drill through the wall and run the pipe through, sealing round it on both sides.\nWe fit the shut-off valve and the double check valve indoors, and the tap on a wall plate outside.\nWith the water back on, we run the tap, check every joint inside and out, and insulate the pipe where it is exposed.",
                BeforeWeArrive = "[home] Choose where on the wall you want the tap. A spot close to the kitchen keeps the pipe inside short.\n[inventory_2] Clear the cupboard under the sink, and anything against the wall on both sides.\n[add_a_photo] Show us the wall. A photo of the outside wall and one of the pipes under the sink, added to your booking, show us the route the pipe will take.",
                Included = "A new outside tap connected to the cold supply\nDrilling the wall and sealing round the pipe\nBackflow protection and a shut-off valve, fitted indoors\nInsulating the exposed pipe\nAdding backflow protection to an existing tap that has none",
                NotIncluded = null,
                Faqs = new[]
                {
                    ("Should I turn my outside tap off in winter?", "Yes. WaterSafe's advice is to disconnect the hose, shut off the outside supply if you can and drain the tap, and fit an insulating cover. The shut-off valve we fit indoors is there for this: close it, then open the tap outside to let the water out."),
                    ("Can I fill a pond or a hot tub from an outside tap?", "Not from one protected only by a double check valve. Water Regs UK classes a hose used to refill a pond, a swimming pool, a spa bath or a hot tub as fluid category 5, the highest risk, unless your water company assesses it otherwise, so ask your water company before you do."),
                },
            },
            ["painting-touch-ups"] = new ServicePageText
            {
                Summary = "Holes, dents and scuffs filled, sanded and painted on walls, ceilings and woodwork, and the whole wall painted where a patch would show.",
                CommonFindings = "[visibility] A patch that shows on a silk or satin wall. Farrow & Ball says filled areas take up paint at a different rate from the wall round them, and that the difference shows far more on paints with a higher sheen. On a wall like that, the paint may need to go from corner to corner.\n[warning] Old paint that may contain lead. Cambridge City Council says a home built before the 1960s that still has its original coats of paint could have some lead in it, and HSE names dry sanding old paint and stripping it with blow lamps among the risky jobs. Old woodwork is rubbed down wet, never dry, and never burnt off.\n[build] An old wall plug left in its hole. Filled over, it shows through again, so it is pulled out, or set below the surface, before the hole is filled.\n[refresh] A crack that keeps coming back in a corner. Where a wall meets the ceiling or a door frame, the two move slightly apart and hard filler cracks again. A flexible decorator's caulk takes the movement.",
                VisitSteps = "We look at the finish and the colour, and tell you whether patches will blend or the wall needs a full coat.\nWe fill each hole, dent and crack, let the filler dry and sand it smooth.\nWe prime the filled spots, so the paint does not sink into them.\nWe paint, with a second coat where the first does not cover.\nWe take up the dust sheets and clean up.",
                BeforeWeArrive = "[inventory_2] If you have the tin the wall was painted with, leave it out: its label gives the paint and the colour. If not, tell us the brand and the colour's name if you know them.\n[checklist] Put a small piece of masking tape next to each mark you want done, so none is missed.\n[home] Move small furniture and pictures away from the walls being painted.",
                Included = "Filling holes, dents and cracks\nSanding and priming the filler\nPainting walls, ceilings, doors, frames and skirting boards\nFlexible caulk in corners that keep cracking",
                NotIncluded = "Plaster that has come away from the wall, or a ceiling damaged by water: that is Plastering & Ceiling Repairs",
                Faqs = new[]
                {
                    ("Will a touch-up show?", "It can. Filled spots take up paint differently from the wall round them, and a silk or satin finish shows that most, which is why we may suggest painting the whole wall. On a flat matt wall a patch is harder to see, though a low light across the wall can still pick it out."),
                    ("Can you paint over a damp patch?", "Not until the cause is mended. A stain left by a leak comes back through new emulsion, so the leak is fixed first, the patch is left to dry, and it is sealed with a stain-blocking primer before it is painted."),
                },
            },
            ["partition-walls-drylining"] = new ServicePageText
            {
                Summary = "A new stud wall to split a room or make a new one, framed in timber or metal, insulated for sound where it is needed and boarded, at a fixed price from a survey.",
                CommonFindings = "[warning] A new room you can only leave through another. A wall that splits a room changes the way out in a fire. The Planning Portal says an inner room, one reached only through another room, may need an escape window of its own, and a new wall between a room and the stairway may need fire resistance, with a door that closes by itself.\n[visibility] One window for two rooms. A wall put up across a room with one window leaves one side without it. A room normally needs both an opening for purge ventilation and background ventilation, such as a trickle vent, so the line of the wall is set at the survey to leave each room its own.\n[construction] A floor that cannot carry the wall. A new internal wall should stand on something strong enough, whether it holds anything up or not. On a timber floor, the Planning Portal advises asking a structural engineer or surveyor to check the joists, and a new beam may be needed under the wall.\n[home] A bedroom beside a bathroom. A new wall that separates a bedroom, or a room with a WC, from another room needs improved sound insulation. Mineral wool in the frame, and the edges sealed, are what stop the sound.",
                VisitSteps = "At the survey we mark out the wall with you, look at the floor and the ceiling it will be fixed to, go through the escape, sound and ventilation the new rooms need, and give you the fixed quote.\nWe fix a rail to the floor and one to the ceiling, into the joists where the wall crosses them, and stand the studs between.\nWe frame the doorway, and fit timber between the studs wherever something heavy will hang.\nWhere the wall has to stop sound, we fill the frame with mineral wool.\nWe board both sides, tape and fill the joints, fit the door lining, the architrave and the skirting, and hang the door.",
                BeforeWeArrive = "[shelves] Tell us where anything heavy will go on the new wall, such as a TV, shelves, a wall cupboard or a radiator, so timber goes in behind the board first. Siniat recommends a timber nogging or a pattress behind large or heavy items.\n[bolt] Decide at the survey where the new room's sockets, switches and light will be, so the cables are in the frame before it is boarded.\n[checklist] Clear the room along the line of the wall before the first day.",
                Included = "A survey and a fixed quote\nA timber or metal stud frame, fixed into the floor, the ceiling and the walls\nA framed doorway with its lining, and the door hung\nTimber behind the board for anything heavy\nSound insulation in the frame where it is needed\nPlasterboard on both sides, the joints taped and filled ready for decorating\nArchitrave and skirting",
                NotIncluded = "Taking out a wall that holds up a floor or the roof, which needs a structural engineer and a beam",
                Faqs = new[]
                {
                    ("Does a stud wall need building regulations approval?", "Generally, yes. The Planning Portal says work to provide a new internal wall generally needs approval under the Building Regulations, because it can change the way out in a fire, the sound between rooms and how the rooms are ventilated."),
                    ("Do I need planning permission for a new internal wall?", "Not usually. Internal alterations should not need an application for planning permission. A listed building is the exception: listed building consent is needed for any significant works, inside or out."),
                },
            },
            ["pipe-repairs"] = new ServicePageText
            {
                Summary = "Damaged lengths of pipe cut out and replaced in copper or plastic: frost splits, nail holes, worn runs and old lead inside the house, tested under full mains pressure.",
                CommonFindings = "[warning] A split left by frost. Pipes in a loft, a garage or along an outside wall freeze in a cold spell. A split pipe needs a new section, and a clamp put on in an emergency is only a stopgap.\n[build] A nail or screw through a pipe. New flooring, a shelf or a picture rail fixed over a hidden pipe. The water often shows only when the fixing is pulled out or works loose.\n[search] Lead pipe. Thames Water's signs: dull grey when unpainted, rounded swollen joints, and shiny silver metal where it is gently scratched.\n[plumbing] Pipes that knock or bang. Usually a pipe that has come loose from its clips, so it moves when a tap or a valve shuts.",
                VisitSteps = "We find the damaged length, and turn off the water at the nearest valve that covers it.\nWe open boxing or lift a floorboard where the pipe runs, and drain the pipe down.\nWe cut out the bad section and join in new pipe, clipped so it cannot move.\nOnce the water is back on, we check every new joint under full pressure, then put the boxing or floorboard back.",
                BeforeWeArrive = "[home] Clear the way to the pipe: the cupboard under the sink, the loft hatch, or the furniture over the floorboards where it runs.\n[add_a_photo] Add a photo of the damage, and of the inside stop valve, to your booking.\n[emergency] Water spraying, or coming through a ceiling, cannot wait for a slot. Turn the water off at the stop valve and call or WhatsApp us.",
                Included = "Finding the damaged length and draining it down\nOpening boxing or lifting floorboards where the pipe runs\nCutting out the damaged section and joining in new copper or plastic pipe\nLead pipe inside the house, as far as the inside stop valve\nClipping loose runs that knock\nTesting every new joint under full pressure",
                NotIncluded = "The underground supply pipe between the outside stop valve and the house, which has to be dug up and relaid\nThe water company's own pipe, up to the outside stop valve: the water company repairs that",
                Faqs = new[]
                {
                    ("Who pays to replace a lead pipe?", "You pay for your part, and the water company for its own. Thames Water owns the pipe from its main to the outside stop valve, and for a house built before 1970 its scheme replaces that part free when the owner replaces their own lead supply pipe."),
                    ("What can I do until a lead pipe is replaced?", "Run the cold kitchen tap for two minutes in the morning, or after a few days away, and use only that tap for drinks and cooking. That is Thames Water's advice. It adds that boiling the water does not help, and that lowering lead matters most if you are pregnant or have young children."),
                },
            },
            ["plastering-ceiling-repairs"] = new ServicePageText
            {
                Summary = "Cracks, holes and loose plaster repaired, walls and ceilings skimmed, and ceilings damaged by a leak boarded again, at a fixed price agreed after a free survey.",
                CommonFindings = "[water_drop] A ceiling stained or bowed after a leak. Plasterboard that has been soaked loses its strength and can sag. Once the leak above is mended, the wet board comes down and new board goes up, taped and skimmed.\n[search] Plaster that sounds hollow when tapped. A blown patch has come away from the wall behind it. It is cut back to firm plaster and filled in layers.\n[home] An old lath and plaster ceiling that sags. In older houses the ceilings are lime plaster pressed through thin strips of timber. Where the plaster has let go of the strips, it is screwed back with plaster washers, or the ceiling is boarded over.\n[warning] A textured ceiling, such as Artex. HSE says to assume a building built or refurbished before 2000 contains asbestos, and textured coatings are among the materials it lists. A coating like that is sampled and tested before it is sanded, scraped or cut.",
                VisitSteps = "At the survey we look at what caused the damage, and give you the fixed quote.\nWe cover the floor and the furniture, and take off the loose plaster or the damaged board.\nWe fix new board where it is needed, and treat the wall so the new plaster grips.\nWe plaster, and skim the whole wall or ceiling where a patch would show.\nWe tell you when the new plaster can be painted.",
                BeforeWeArrive = "[emergency] If a ceiling is bulging with water, keep everyone out of the room under it and leave its light switched off. If water is still coming through, that is an emergency: call us or message us on WhatsApp.\n[home] Clear the room as far as you can. What has to stay is covered.\n[info] If a ceiling has a textured finish and you know when it went up, tell us at the survey.",
                Included = "A free survey and a fixed quote\nPatching cracks, holes and loose plaster\nSkimming walls and ceilings\nNew plasterboard for a ceiling damaged by water\nCoving fitted, or a short length matched to the old",
                NotIncluded = "Removing a textured coating that contains asbestos",
                Faqs = new[]
                {
                    ("When can new plaster be painted?", "When it is thoroughly dry, which is what British Gypsum asks for its Thistle plasters. Until then it allows only a permeable paint, because that lets the plaster go on drying underneath."),
                    ("Can an Artex ceiling be plastered over?", "Usually, yes: once it is firm, it is skimmed over and the old coating stays in place underneath. If it may be from before 2000, a sample is tested for asbestos first, because sanding or scraping it would put any fibres into the air."),
                },
            },
            ["property-maintenance"] = new ServicePageText
            {
                Summary = "About three hours of handyman repairs and checks round the whole home in one visit, from your list, with every alarm tested.",
                CommonFindings = "[health_and_safety] A smoke alarm that stays silent. Every test button is pressed on the visit. For a landlord, the Smoke and Carbon Monoxide Alarm (England) Regulations 2015 ask for each alarm to be in proper working order on the day a new tenancy begins.\n[water_drop] Sealant round the bath or shower that has gone black or come away. Water gets behind it each time the bath or shower is used, so it is cut out and run again.\n[home] A door that sticks in winter and swings free in summer. NHBC says a house expands and shrinks with the temperature and humidity through the year, and doors can stick in their frames or swing open. The hinges and the catch are adjusted, or the door is eased where it binds.\n[build] A loose handrail on the stairs. It is fixed first, because it is the fitting people put their weight on.",
                VisitSteps = "We walk round with your list and decide with you what comes first.\nWe work through it room by room, then outside.\nWe press the test button on every smoke and carbon monoxide alarm.\nWe tell you about anything that needs a quote, a survey or another trade.\nBefore we leave, we go through what was done and what is left.",
                BeforeWeArrive = "[checklist] Walk round first and note the jobs room by room, then put the list and a photo of each in your booking.\n[key] If the home is let, give your tenants at least 24 hours' notice. GOV.UK's guidance for landlords asks for that before entering to inspect or carry out repairs.\n[inventory_2] Have the parts you have chosen there, such as new handles, a toilet seat or light bulbs.",
                Included = "Your list of handyman repairs, inside and out\nA test of every smoke and carbon monoxide alarm\nResealing round baths, showers and sinks\nAdjusting doors that stick, and cupboard doors that hang crooked\nFixing back loose handrails, handles and rails",
                NotIncluded = "Plumbing, which is General Plumbing Maintenance\nThe yearly gas safety check, which is for a Gas Safe registered engineer\nThe electrical safety report a landlord needs at least every five years, which is for a qualified electrician",
                Faqs = new[]
                {
                    ("Does this visit cover a landlord's gas and electrical safety checks?", "No. The HSE says a landlord's gas appliances and flues must be checked by a Gas Safe registered engineer at least every 12 months, and the rules for rented homes ask for the electrics to be checked at least every 5 years by a properly qualified person. This visit is the handyman work around those checks."),
                    ("How is this different from a General Handyman Call-Out?", "In time and in reach. A call-out is an hour for a few small jobs. Property Maintenance is about three hours for a whole list round the house, with the checks that go with it, such as testing every alarm."),
                },
            },
            ["radiator-trv-replacement"] = new ServicePageText
            {
                Summary = "A radiator swapped for a new one, a manual valve changed for a thermostatic one (TRV), or a stuck or weeping valve replaced. The system is refilled, bled and checked before we leave.",
                CommonFindings = "[refresh] A stuck TRV pin. Under the head is a small pin that the head pushes in and out; after a summer with the heating off it can stick, and the radiator stays hot or cold whatever the dial says.\n[water_drop] A weeping valve. Water creeps out round the spindle, or at the nut where the valve joins the radiator, and leaves a stain or rust on the floor below.\n[warning] A radiator rusting through. Small leaks start along the bottom or the seams of an old steel one. Once it has rusted through, it is replaced, not repaired.\n[info] A TRV in the room with the room thermostat. BEAMA's guidance on the Building Regulations puts a TRV on every radiator except those in the room where the room thermostat is, so that radiator keeps a plain valve.\n[home] A TRV hidden behind a curtain or a sofa. Worcester Bosch says a TRV should be in the open, not covered by curtains or furniture: a covered head reads the warm air trapped round it and turns the radiator down too early.",
                VisitSteps = "We turn the heating off and let the system cool.\nWe close the valves either side, or drain the water down below the radiator when a valve itself is being changed.\nWe fit the new radiator or valve, altering the pipe ends if the new radiator's connections sit in a different place.\nWe refill the system, bleed every radiator on it, and top up the pressure on a sealed system.\nWe run the heating and check that every new joint stays dry once it is hot.",
                BeforeWeArrive = "[timer] Turn the heating off before we come, so the water has cooled when we start.\n[search] Measure the radiator you want replaced: its width, its height, and the distance between the two pipes where they come out of the floor or the wall. Add the figures, or a photo with a tape measure in it, to your booking.\n[inventory_2] Move furniture back from the radiator and lift anything off the floor beneath it: a little dark water comes out when one is taken off.",
                Included = "Changing a manual valve for a TRV, or an old TRV for a new one\nReplacing a radiator with one of the same size or a new size\nAltering the pipe ends to suit a new radiator\nRefilling, bleeding and repressurising the system afterwards\nChecking every new joint with the heating hot",
                NotIncluded = "Work on the boiler itself: that is for our Gas Safe registered engineer, under Boiler Installation & Servicing",
                Faqs = new[]
                {
                    ("Can a TRV be changed without draining the heating?", "The head, yes: it unscrews from the valve body, and a new one goes on with the water still in. Changing the valve body means draining the water down below it first, then refilling and bleeding the system."),
                    ("Does every radiator need a TRV?", "Every one except in the room with your room thermostat, by BEAMA's guidance. Since June 2022 in England, a new boiler in an existing home has to come with thermostatic control in each room, and TRVs are the usual way to give it."),
                    ("Will a new radiator fit my old pipes?", "If its connections are in the same place as the old one's, yes, with no change to the pipes. A different size usually means altering the two pipe ends, and the measurements in your booking let us plan for that."),
                },
            },
            ["shelf-installation"] = new ServicePageText
            {
                Summary = "Floating shelves, shelves on brackets, wall uprights and alcove shelves, put up level with fixings chosen for the wall and for what they will carry.",
                CommonFindings = "[warning] Plasterboard stuck to brick. Some walls that sound hollow are boards fixed to the brick with dabs of adhesive, leaving a gap behind. A short plug holds only the board, so the fixing has to go through to the brick.\n[shelves] A floating shelf that droops. Its hidden rods turn the load into leverage on the fixings, so it needs solid masonry or studs, and a flat wall.\n[home] Alcoves that are not square. The walls either side of a chimney breast are rarely true in an older house, so each alcove shelf is cut to its own alcove.\n[construction] Old plaster that crumbles round the drill. In older houses the plaster can be soft, so the fixing is set in the brick behind it, not in the plaster.",
                VisitSteps = "We agree the height and the spacing with you and mark a level line.\nWe check the wall along that line for cables and pipes.\nWe cut the shelves to length where they need it, and fix the brackets or battens.\nWe put each shelf up, check it is level, and lean on it to test the fixings.",
                BeforeWeArrive = "[shelves] Have the shelves and brackets there, and say in your booking what will go on them: the weight decides the fixing.\n[inventory_2] Clear the wall and the floor in front of it.\n[add_a_photo] Put a photo of the wall in your booking, and for an alcove, one with a tape measure across it.",
                Included = "Finding what the wall is made of, and checking it for cables and pipes\nFixings chosen for the wall and the load\nCutting shelves and battens to fit an alcove\nFixing every shelf level, and testing it before we leave",
                NotIncluded = "Built-in alcove units with doors or cupboards, made to measure: those are Custom Carpentry & Boxing-In, quoted after a survey",
                Faqs = new[]
                {
                    ("How much weight can a floating shelf hold?", "No more than its maker's figure, and that only when it is fixed into brick, block or studs. On plasterboard alone it holds far less, which is why we ask in the booking what will go on it."),
                    ("Can you put shelves on a plasterboard wall?", "Yes. Light ones can hang on cavity fixings in the board. Heavy ones need timber behind the board, as Siniat, a plasterboard maker, advises, so they go onto the studs."),
                },
            },
            ["shower-installation"] = new ServicePageText
            {
                Summary = "Mixer, power and electric showers fitted, chosen to suit your boiler or cylinder, with the pipework connected and tested, and any wiring done by a registered electrician we bring in.",
                CommonFindings = "[construction] A valve built into the wall, or one on its face. A concealed valve needs the wall opened for its pipes and then retiled. A bar mixer sits on the tiles and takes its pipes through them, so the tiling can stay.\n[warning] A handset that can reach the toilet. Water Regs UK treats a shower hose that can reach into a toilet or bidet as the highest risk to drinking water. A clip that holds the hose back, a shorter hose or a fixed head removes the risk.\n[water_drop] A shower head that can lie in the bath water. The handset has to stay a set gap above the rim of the bath or the tray, or the supplies need double check valves, so that used water cannot be drawn back into the pipes.\n[plumbing] Hot and cold that can cross. Water Regs UK asks for check valves on both supplies to a shower valve, so that under a fault cold water at mains pressure cannot push into the hot, or hot water into the cold mains.",
                VisitSteps = "We look at the boiler or cylinder, and check the shower you have chosen suits it before anything is cut.\nWith the water off, we run the pipes to where the valve will go, with a check valve and an isolating valve on each supply.\nWe fix the valve, the rail or the fixed head, and the hose, set so the handset cannot reach the toilet or lie in the water.\nOnce the supply is back on, we run the shower at full heat and full cold, and check every joint for leaks.",
                BeforeWeArrive = "[add_a_photo] Show us the boiler. A photo of it, of the cylinder and loft tank if you have them, and of the wall where the shower will go, added to your booking, tells us which showers will work.\n[inventory_2] If you have bought the shower, keep it in its box with the instructions, so every part can be checked before we start.\n[home] Clear the bath or the tray and the floor round it.",
                Included = "Checking the shower suits your boiler or cylinder\nRunning the pipework to the valve and connecting it\nA check valve and an isolating valve on each supply\nFitting the valve, the rail or fixed head, and the hose\nA hose clip where the handset could otherwise reach the toilet\nThe wiring for an electric shower or a pump, by a registered electrician we bring in, who certifies it\nTesting every joint for leaks",
                NotIncluded = "Tiling round a new valve built into the wall: that is Wall & Floor Tiling, priced after a survey",
                Faqs = new[]
                {
                    ("Can I have a power shower with a combi boiler?", "Not as a rule, and you do not need one. A combi already delivers mains pressure, which suits a mains-pressure mixer shower, while Worcester Bosch describes the pump-assisted kind as made for low-pressure systems fed from a tank."),
                    ("Will a new shower give me more pressure?", "Only as much as your system has. A mixer gives the pressure its supplies already have. On a tank-fed system that depends on how far the loft tank sits above the shower head, which is why a power shower adds a pump there."),
                },
            },
            ["silicone-mastic-resealing"] = new ServicePageText
            {
                Summary = "Split, lifted or mouldy sealant cut out round baths, showers, basins and sinks, and a new bead of sanitary silicone run on a clean, dry joint.",
                CommonFindings = "[water_drop] Black mould inside the bead. Once mould has grown into the silicone, a cleaner only reaches the surface. UniBond's own advice is that sealant in that state has to come out and be replaced.\n[warning] A seal that splits along the length of the bath. A bath drops a little under the weight of water and a person, so a bead run on an empty bath is stretched every time it is filled. We fill the bath before sealing and leave it full while the bead cures.\n[build] A bath or tray that moves when you stand in it. If its feet or frame are loose, the bead tears again within weeks. We check them and tighten or adjust them first.\n[refresh] New sealant over old. Fresh silicone does not stick to old silicone or to the film it leaves behind, so the new bead peels away at the edges. Every trace of the old one is cut and cleaned off.",
                VisitSteps = "We cut out the old sealant, clean off what is left of it, and let the joint dry.\nWe fill the bath with water, so it sits as it will when in use.\nWe mask the edges of a wide joint and run one continuous bead, smoothed into the corner.\nWe leave the bath full and tell you how long the sealant needs before the bath or shower is used.",
                BeforeWeArrive = "[inventory_2] Clear bottles and soap from the bath edge, the shelves and round the sink.\n[timer] If you can, leave the shower unused for a few hours before we come, so the joint is dry when we seal it.\n[warning] If there is a stain on the ceiling under the bathroom, say so in your booking. The leak may be the seal, or it may be the waste or a pipe under the bath.",
                Included = "Cutting out the old sealant and cleaning the joint\nBaths, shower trays, basins and kitchen sinks\nTightening or adjusting the feet of a bath that moves\nFilling the bath before it is sealed\nSanitary silicone with a mould inhibitor",
                NotIncluded = "Regrouting or replacing tiles: that is Wall & Floor Tiling\nA leak from the waste or a pipe under the bath: that is Leak Repairs",
                Faqs = new[]
                {
                    ("How long before I can use the bath or shower?", "Usually about a day. Sanitary silicone cures from the outside in, and the time on the tube is the one to follow. Bostik's data sheet, for example, gives about 24 hours for each 2mm of depth, so a deep joint takes longer."),
                    ("Why does new silicone go black again?", "Because mould grows where water stays. Silicone with a mould inhibitor holds it off for longer, but a bathroom that is aired after every bath or shower, with the bead wiped dry, keeps it clean longest."),
                },
            },
            ["tap-repairs"] = new ServicePageText
            {
                Summary = "A dripping tap, a stiff handle or water round the base, fixed by changing the worn washer, cartridge or O-ring rather than the whole tap. New taps fitted too.",
                CommonFindings = "[water_drop] A worn washer. In taps with separate hot and cold heads, the spout keeps dripping however hard the head is turned.\n[construction] A worn ceramic cartridge. In quarter-turn and mixer taps, the handle turns but the water does not stop cleanly.\n[refresh] A perished O-ring. Water gathers round the base of the spout while the tap runs, or creeps out under the head.\n[info] A scaled or worn valve seat. A new washer will not seal on it, so the seat is cleaned or re-cut first.\n[home_repair_service] A tap that turns on the basin. The back nut underneath has worked loose, and every turn pulls on the pipe joints below.",
                VisitSteps = "We shut the water off at the isolating valve under the basin or sink, or at the stop valve if there is none.\nWe take the tap apart and show you the worn part.\nWe fit the new washer, cartridge or O-ring, or tell you plainly if the tap is past repair.\nWe turn the water back on and check that it closes fully and stays dry underneath.",
                BeforeWeArrive = "[plumbing] Find your inside stop valve and check that it turns. Thames Water says it is usually under the kitchen sink, and that it closes clockwise.\n[inventory_2] Clear the cupboard under the basin or sink, so the pipes can be reached.\n[add_a_photo] Add a photo of the tap to your booking, with the maker's name if one is printed on it: cartridges differ from one make to the next.",
                Included = "Finding which part has worn, and why\nNew washers, O-rings and ceramic cartridges\nCleaning or re-cutting a scaled valve seat\nTightening a loose tap from underneath\nFitting a new tap, agreed and priced before it goes in",
                NotIncluded = "A tap that will not turn off at all and cannot be isolated: call or WhatsApp us, as it cannot wait for a booked slot",
                Faqs = new[]
                {
                    ("Is it worth repairing a tap, or should I replace it?", "Usually repair. A washer, an O-ring or a cartridge is a small part, and the body of a tap rarely wears out. A new tap makes more sense when the body is cracked, the finish is coming away, or no cartridge is made for that model any more."),
                    ("How much water does a dripping tap waste?", "Over 12,000 litres a year if it drips once a second, by Waterwise's figure. On a water meter you pay for every litre of it."),
                    ("Will you have the right part for my tap?", "A photo of the tap with your booking is the surest way. Ceramic cartridges are made to fit one make and range, so we match it from the photo. A part we do not carry is priced and agreed with you before it is fitted."),
                },
            },
            ["toilet-repairs"] = new ServicePageText
            {
                Summary = "A running, slow-filling or leaking toilet, fixed by finding the one failed part (flush valve, fill valve, seal or pan connector) and changing it.",
                CommonFindings = "[water_drop] A flush valve that no longer seals. Water trickles into the pan long after the flush. WaterSafe finds this most on dual-flush toilets with a push button.\n[refresh] A fill valve that does not shut off. The cistern keeps filling and the water runs away through the overflow.\n[build] A worn seal between the cistern and the pan. On a close-coupled toilet, water collects on the floor behind the pan after each flush.\n[warning] A cracked or loose pan connector. Water, or a smell, where the back of the pan joins the soil pipe.\n[checklist] A broken button or lever link. The flush works only now and then, or the button stays down.",
                VisitSteps = "We close the valve on the pipe that feeds the cistern and flush it empty.\nWe find the failed part and show it to you.\nWe fit the new valve, seal or connector, and set the water level in the cistern to its mark.\nWe flush several times and check that the floor behind the pan stays dry.",
                BeforeWeArrive = "[search] Not sure it leaks? WaterSafe's test: 30 minutes after a flush, wipe the back of the pan dry and lay a dry sheet of toilet paper there for a few hours. A wet or torn sheet means water is getting past the flush valve.\n[add_a_photo] Lift the cistern lid and add a photo of the inside, and of the flush button, to your booking.\n[home] Clear the floor round the toilet and anything kept on the cistern lid.",
                Included = "Flush valves, fill valves and their seals\nThe seal and bolts of a close-coupled toilet\nPan connectors\nButtons, levers and the links inside the cistern",
                NotIncluded = "A blocked toilet: book Blocked Drains, which covers toilets",
                Faqs = new[]
                {
                    ("Why does my toilet keep running?", "Either the flush valve no longer seals, so water trickles into the pan, or the fill valve does not shut, so the cistern fills into its overflow. WaterSafe names these two as the usual causes. Both sit inside the cistern."),
                    ("Is water on the floor behind the toilet always a leak?", "Not always. A cold cistern sweats in winter and the drops run down the back of the pan. Dry everything, flush, and watch where water appears first: the joint under the cistern, the connector at the back, or the supply pipe. That tells us which part to bring."),
                },
            },
            ["tv-mounting"] = new ServicePageText
            {
                Summary = "A flat-screen TV fixed to brick, block or plasterboard on a bracket that matches it, level and at the height you choose, with the cables tidied.",
                CommonFindings = "[search] A plasterboard wall. It sounds hollow when you knock on it. A bracket screwed into the board alone can pull out, so we find the studs and fix into those.\n[bolt] A socket under the spot. Electrical Safety First says cables buried in a wall must run straight up, down or across from a socket or switch, so the wall right above a socket is where a cable is most likely to be. We trace it with a detector before drilling.\n[info] A bracket that does not match the TV. The holes on the back of a TV are set to a VESA size, such as 200 by 200 millimetres, and a bracket's box lists the sizes and the weight it takes.\n[warning] An arm that swings out. With the TV pulled away from the wall, the top fixings carry far more pull than on a flat bracket, so an arm needs masonry or two studs behind it.",
                VisitSteps = "We agree the position and the height with you before anything is drilled.\nWe find what the wall is made of and check the spot for cables and pipes.\nWe fix the bracket level, into the masonry or into the studs.\nWe hang the TV, check that it sits level and that any arm locks, and tidy the cables.",
                BeforeWeArrive = "[visibility] Mark where you want the middle of the screen with a piece of masking tape, and look at it from where you sit.\n[checklist] If you have bought a bracket, check that its box lists your TV's VESA size and a weight above your TV's. Both are in the TV's manual.\n[inventory_2] Move the TV stand and anything else away from that wall.\n[add_a_photo] Photograph the wall and the back of the TV, and add both to your booking.",
                Included = "Finding what the wall is made of, and checking it for cables and pipes\nFixing the bracket into the masonry or into the studs\nHanging the TV level, and checking that any arm locks\nTidying the cables into a cover on the wall",
                NotIncluded = null,
                Faqs = new[]
                {
                    ("Can a TV go on a plasterboard wall?", "Yes, when the bracket is fixed to the timber studs inside the wall: that is RoSPA's advice for plasterboard walls. If there is no stud where you want the screen, we show you where the nearest ones allow it."),
                    ("My TV stays on its stand. Can it be made safe for small children?", "Yes, with an anti-tip strap, fixed to the back of the set and to a bracket on the wall, which is what RoSPA advises. RoSPA knows of eight babies and young children in the UK killed by a falling television since July 2008. We can fit a strap on the same visit."),
                },
            },
            ["wall-floor-tiling"] = new ServicePageText
            {
                Summary = "Walls and floors tiled in ceramic, porcelain or stone, on a base made ready for the tile's weight, quoted after a free survey at your home.",
                CommonFindings = "[build] Floorboards that move underfoot. A floor that flexes cracks the grout and then the tiles, so loose boards are screwed down firmly before the new base goes over them.\n[construction] Heavy tiles for a plastered wall. Instarmac, the adhesive maker, gives the most a wall can carry as 20kg a square metre on gypsum plaster and 32kg on plasterboard with no skim, adhesive and grout included. Large porcelain or stone can weigh more, so the wall is boarded to take it.\n[timer] New plaster that has not dried out. British Gypsum says tiles should not go on until the plaster and the wall behind it are dry.\n[search] A floor that is out of level. Long tiles show every dip as a lip at their edges, so the floor is levelled with a levelling compound first.",
                VisitSteps = "At the survey we measure, look at the wall or floor the tiles will go on, agree the layout with you, and give you the fixed quote.\nWe take off the old tiles or floor covering where they have to come off, and prepare the base: boards, a membrane or a levelling compound.\nWe set the tiles out from the centre lines, so the cut tiles at the edges are even.\nWe fix the tiles, cutting round pipes, sockets and corners.\nWe grout, and seal with silicone where the tiles meet a bath, a shower tray or a worktop.",
                BeforeWeArrive = "[add_a_photo] For the survey, have the tiles you like, or pictures of them, and their size.\n[inventory_2] Keep a few spare tiles from the same batch. The batch or shade number is on the box, and a later repair is easier with a tile that matches.\n[home] A tiled floor sits higher than carpet or vinyl, so a door that opens over it may need trimming. Tell us which doors.",
                Included = "Measuring up and a fixed quote at the survey\nPreparing the wall or the floor\nA backer board or a membrane over timber floors\nLevelling an uneven floor\nCutting round pipes, sockets and corners\nGrouting, and silicone along baths, trays and worktops\nSealing natural stone",
                NotIncluded = null,
                Faqs = new[]
                {
                    ("Can tiles go straight onto floorboards?", "No. The Tile Association says that under BS 5385-3:2024, the British Standard for floor tiling, timber boards are no longer recommended for tiling directly, and a layer such as a tile backer board or an uncoupling membrane goes over them first."),
                    ("Can new tiles go over old ones?", "Sometimes. Every old tile has to be firmly stuck, and the wall has to carry the weight of both layers. Where either is in doubt, the old tiles come off first."),
                },
            },
            ["wall-mounting"] = new ServicePageText
            {
                Summary = "Pictures, heavy mirrors, whiteboards and gallery walls hung level, on fixings chosen for the wall and for what each piece weighs.",
                CommonFindings = "[warning] A mirror that is heavier than it looks. Glass 4mm thick weighs about 10kg a square metre before the frame is counted, so a large mirror goes on two fixings rated for it, or on a split batten, not on one hook.\n[build] Plasterboard with no stud where the piece has to go. A cavity fixing such as a spring toggle opens out behind the board. Rawlplug's figures for its spring toggle in 12.5mm board come to roughly 12 to 16kg a fixing, so a heavy piece is spread over several of them.\n[info] One wire across the back of a heavy frame. The wire and its two screw eyes then carry all the weight, and the frame leans forward off the wall. Two D-rings on two fixings hold it flat and keep it level.",
                VisitSteps = "We find out what the wall is made of and scan each spot for pipes and cables before drilling.\nFor a gallery wall, we set the frames out on the floor, then tape paper outlines of them to the wall so you can see the layout first.\nWe mark, drill and fix, and hang each piece level.\nWe check every piece is firm on its fixings before we leave.",
                BeforeWeArrive = "[checklist] Say in your booking what is going up, how many pieces, and the weight of anything heavy. A mirror's weight is usually on its box or its listing.\n[key] If you rent, check your tenancy agreement, or ask your landlord, before holes go in the walls.\n[home] Clear the wall and the floor in front of it.",
                Included = "Pictures and frames, one at a time or as a gallery wall\nMirrors, heavy ones included\nWhiteboards and noticeboards\nFixings chosen for the wall and the weight",
                NotIncluded = "TVs: that is TV Mounting\nShelves: that is Shelf Installation\nA mirror with a light or a demister pad that has to be wired in",
                Faqs = new[]
                {
                    ("How heavy a mirror can go on plasterboard?", "It depends on the fixings, not the board alone. Each cavity fixing has a load its maker gives, so a heavy mirror is spread over several of them, or fixed into the timber studs. Tell us its weight when you book."),
                    ("Can pictures go up without drilling holes?", "Yes, if the room has a picture rail. Pictures hang from it on hooks and cord, once we have checked the rail itself is firmly fixed. Mirrors and anything heavy are fixed into the wall."),
                },
            },
            ["washing-machine-dishwasher-install"] = new ServicePageText
            {
                Summary = "A washing machine or dishwasher connected to the water and the waste, set up as its maker says, and run to check for leaks. A new valve or waste added where there is none.",
                CommonFindings = "[warning] Transit bolts still in. They lock a washing machine's drum for delivery, and a machine run with them in shakes hard on its first spin.\n[search] A machine that empties while it fills. When the waste hose is pushed too far down the standpipe, or the standpipe is too low, the water siphons out as fast as it goes in. The maker's instructions give the height the waste should reach.\n[water_drop] A hose kinked against the wall. Pushing an appliance back into its space can fold the fill or waste hose behind it, which slows the water or splits the hose in time.\n[inventory_2] A dishwasher that cannot be pulled out. Bosch's installation guide asks for the plug and hoses to reach at least 60 cm, so the dishwasher comes out of its housing for maintenance without being disconnected.",
                VisitSteps = "We turn off the valve and disconnect the old appliance, if there is one, and check the valve and waste it used.\nOn a new washing machine, we take out the transit bolts and fit the blanks.\nWe connect the fill hose to the cold valve and the waste to the trap under the sink or to the standpipe, with no kinks in either.\nWe level a freestanding machine, or fix an integrated dishwasher into its housing with the bracket supplied.\nWe run it and watch every joint and the waste while it fills and empties.",
                BeforeWeArrive = "[inventory_2] Have the new appliance in the kitchen, and clear the space and the cupboard under the sink.\n[bolt] Check there is a socket the plug can reach. Bosch's instructions plug a machine into an ordinary socket.\n[add_a_photo] Send the model number. Add it to your booking, with a photo of the space and of the valves and pipes there now.",
                Included = "Connecting a washing machine, washer-dryer or dishwasher to the water and the waste\nTaking out the transit bolts and levelling a freestanding machine\nA new valve or waste connection where there is none\nFixing an integrated dishwasher into its housing\nA test run with every joint checked",
                NotIncluded = "A new socket for the appliance: that is Minor Electrical Tasks, at the handyman rate\nNew kitchen units, or cutting a space for the appliance: that is Kitchen Fitting & Alterations, priced after a survey",
                Faqs = new[]
                {
                    ("Does a washing machine need a hot water connection?", "Usually not, but check its instructions. Bosch's steps connect the fill hose to the cold supply only, and a machine with one inlet heats its own water."),
                    ("Can a washing machine and a dishwasher share the sink waste?", "Yes. A sink trap with two connections on its side takes both waste hoses, and each hose is looped up high under the worktop so water from the sink cannot run back into the appliance."),
                },
            },
        };
    }
}
